{"CommandLine":"Get-ChildItem -Path C:\AI-BS\frontend -Recurse -Include *.jsx | ForEach-Object {
    $c = Get-Content $_.FullName -Raw
    if ($c -match "v5\.13\d+\.0") {
        $c = $c -replace "v5\.13\d+\.0", "v5.138.0"
        Set-Content $_.FullName $c
        Write-Host "Updated $($_.FullName)"
    }
}
","Cwd":"C:\AI-BS","WaitMsBeforeAsync":5000,"toolAction":"Sweeping frontend version badges to v5.138.0","toolSummary":"Update version badges"}
